-- Name: sy_jobsite_id_jobsite_seq; Type: SEQUENCE; Schema: shyrka; Owner: -
--

CREATE SEQUENCE shyrka.sy_jobsite_id_jobsite_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


