-- Name: sy_reflex; Type: TABLE; Schema: shyrka; Owner: -
--

CREATE TABLE shyrka.sy_reflex (
    id_reflex integer NOT NULL,
    event text NOT NULL,
    tool_matcher text DEFAULT ''::text NOT NULL,
    scope text DEFAULT 'global'::text NOT NULL,
    path_glob text,
    pattern text,
    handler text,
    action text DEFAULT 'deny'::text NOT NULL,
    reason text NOT NULL,
    fail_mode text DEFAULT 'closed'::text NOT NULL,
    active smallint DEFAULT 1 NOT NULL,
    date_add timestamp without time zone DEFAULT now() NOT NULL,
    date_upd timestamp without time zone DEFAULT now() NOT NULL,
    tier text DEFAULT 'bras'::text NOT NULL,
    CONSTRAINT chk_sy_reflex_pattern_safe CHECK (shyrka.is_safe_regex(pattern)),
    CONSTRAINT sy_reflex_action_check CHECK ((action = ANY (ARRAY['deny'::text, 'warn'::text, 'allow'::text]))),
    CONSTRAINT sy_reflex_fail_mode_check CHECK ((fail_mode = ANY (ARRAY['open'::text, 'closed'::text]))),
    CONSTRAINT sy_reflex_tier_check CHECK ((tier = ANY (ARRAY['tronc'::text, 'bras'::text])))
);


--
-- Name: TABLE sy_reflex; Type: COMMENT; Schema: shyrka; Owner: -
--

COMMENT ON TABLE shyrka.sy_reflex IS 'Decentralized reflexes — active guard rules (settings.json -> DB -> decision bridge).';


--
-- Name: CONSTRAINT chk_sy_reflex_pattern_safe ON sy_reflex; Type: COMMENT; Schema: shyrka; Owner: -
--

COMMENT ON CONSTRAINT chk_sy_reflex_pattern_safe ON shyrka.sy_reflex IS 'Third line of anti-ReDoS defense (after the _safe_search runtime guard and the Python gate). Prevents a catastrophic pattern from entering the DB through direct INSERT/UPDATE.';


